function hex(h){const n=parseInt(h.slice(1),16);return{r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255};}
function solid(h){return[{type:'SOLID',color:hex(h)}];}
const C={brand:"#6347EB",bg:"#F7F6FB",primary:"#1A1A1F",secondary:"#86868F",coral:"#FF7A59",warn:"#E8930C",warnSoft:"#FDF3E3",good:"#1FA971",goodSoft:"#E6F6EF"};
async function T(chars,size,style,color){const t=figma.createText();t.fontName={family:"DM Sans",style};t.fontSize=size;t.characters=chars;t.fills=solid(color);t.lineHeight={value:Math.round(size*1.25),unit:"PIXELS"};return t;}
async function recolor(inst,color){for(const v of inst.findAll(n=>n.type==="VECTOR"||n.type==="ELLIPSE")){try{if(v.fills&&v.fills.length)v.fills=solid(color);}catch(e){}try{if(v.strokes&&v.strokes.length)v.strokes=solid(color);}catch(e){}}}

