// ---- shared builders ----
async function shell(frame){
  const sb=await (await figma.getNodeByIdAsync("1:25")).createInstance();frame.appendChild(sb);sb.x=0;sb.y=0;
  const hi=await (await figma.getNodeByIdAsync("1:35")).createInstance();frame.appendChild(hi);hi.x=0;hi.y=778;
}
function contentFrame(){
  const f=figma.createFrame();f.name="Content";f.fills=[];f.layoutMode="VERTICAL";f.itemSpacing=10;
  f.paddingLeft=16;f.paddingRight=16;f.paddingTop=12;f.paddingBottom=8;
  return f;
}
async function addHeader(frame,title,hasPlus){
  const h=(await figma.getNodeByIdAsync("9:2")).createInstance();
  frame.appendChild(h);h.x=0;h.y=44;
  h.findOne(n=>n.name==="Title").characters=title;
  h.findOne(n=>n.name==="Action").visible=!!hasPlus;
  return h;
}
async function addTabBar(frame){
  const tb=(await figma.getNodeByIdAsync("9:8")).createInstance();
  frame.appendChild(tb);tb.x=0;tb.y=752;
  return tb;
}
function makeScreen(name,x){
  const f=figma.createFrame();f.name=name;f.resize(375,812);f.fills=solid(C.bg);f.clipsContent=true;f.x=x;f.y=0;
  return f;
}

