function nav(node,dest){
  node.reactions=[{trigger:{type:"ON_CLICK"},actions:[{type:"NODE",destinationId:dest.id,navigation:"NAVIGATE",transition:{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}},resetVideoPosition:false,resetScrollPosition:false,resetComponentState:false}]}];
}
// 01 -> 02 via Bill & Utilities card
const cc2=S1.findOne(n=>n.name==="Card_BillUtilities");
nav(cc2,S2);
// 01 -> 03 via Credit score entry
const ce=S1.findOne(n=>n.name==="CreditScoreEntry");
nav(ce,S3);
// 02 back -> 01
const back2=S2.findOne(n=>n.name==="Back");
nav(back2,S1);
// 03 back -> 01
const back3=S3.findOne(n=>n.name==="Back");
nav(back3,S1);
return JSON.stringify({
  cc2:cc2.reactions.length,ce:ce.reactions.length,back2:back2.reactions.length,back3:back3.reactions.length
});

